style.css:
@-moz-document domain("google.com") {
/* === BACKGROUND FIX (FULL SCREEN IMAGE) === */
  body {
    background: url("https://images3.alphacoders.com/138/thumb-1920-1384215.png") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* REMOVE WHITE STRIP AT THE BOTTOM */
  #footer, #fbar, #fbarcnt {
    background: transparent !important;
    border: none !important;
  }

  /* === SEARCH BUTTONS (FULL SEVIKA STYLE) === */
  .FPdoLc input[name="btnK"], .FPdoLc input[name="btnI"] {
    font-size: 18px !important;
    font-family: 'Arial', sans-serif !important;
    font-weight: bold !important;
    color: white !important;
    background: #5a0e0e !important; /* Dark Red */
    border: 2px solid #940000 !important; /* Blood Red */
    padding: 10px 25px !important;
    text-transform: uppercase !important;
    letter-spacing: 1px !important;
    transition: all 0.3s ease-in-out !important;
  }

  /* BUTTON HOVER EFFECT */
  .FPdoLc input[name="btnK"]:hover, .FPdoLc input[name="btnI"]:hover {
    background: #940000 !important;
    border-color: #5a0e0e !important;
  }

  /* CHANGING BUTTON TEXT */
  .FPdoLc input[name="btnK"]::after {
    content: "TIME TO HUNT" !important;
    display: block !important;
  }

  .FPdoLc input[name="btnI"]::after {
    content: "NO TURNING BACK" !important;
    display: block !important;
  }

  /* HIDING ORIGINAL TEXT */
  .FPdoLc input[name="btnK"], .FPdoLc input[name="btnI"] {
    color: transparent !important;
    text-shadow: none !important;
  }

  /* === BOTTOM TEXT (SEVIKA QUOTES) === */
  #fbar, #fbarcnt, footer {
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    background: rgba(0, 0, 0, 0.8) !important;
    color: white !important;
    font-size: 14px !important;
    font-family: 'Arial', sans-serif !important;
    text-transform: uppercase !important;
  }

  /* CUSTOM QUOTES */
  #fbar::after {
    content: "NEVER LOSE FOCUS | TRUST GETS PEOPLE KILLED | THE STRONG SURVIVE" !important;
    display: block !important;
    text-align: center !important;
    width: 100% !important;
  }
}
